# Generated by manage.py generate_test_cases.
"""Inbox calendar navigation uses effective shared preferences without selecting new views."""

import json
import re

from django.contrib.contenttypes.models import ContentType
from django.http import HttpResponse
from django.urls import reverse

from bloomerp.models.communication.calendar import CalendarEvent
from bloomerp.models.communication.inbox.inbox import Inbox
from bloomerp.models.users.user_list_view_preference import UserListViewPreference
from bloomerp.services.preference_services import PreferenceManager
from bloomerp.tests.base import BloomerpViewTestCase, ExpectedResult, RequestScenario
from bloomerp.tests.communication.inbox_calendar_fixtures import InboxCalendarFixtures


class TestInboxCalendarView(InboxCalendarFixtures, BloomerpViewTestCase):
    view_name = "inbox_calendar"

    def extendedSetup(self) -> None:
        """Create an accessible shared reference and record existing list-view preferences."""
        self.prepare_calendar()
        self.preference_count = UserListViewPreference.objects.count()

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Require Inbox and event permissions and retain a usable return path."""
        kwargs = {"inbox_id": self.source.pk}
        return [
            RequestScenario(
                name="Apply persists private selections per inbox",
                method="POST",
                user=self.actor,
                view_kwargs=kwargs,
                data={
                    "selection": json.dumps(
                        {
                            "inboxes": [str(self.source.pk)],
                            "users": [str(self.owner.pk)],
                        }
                    )
                },
                expected=ExpectedResult(response_validators=self.selection_saved),
            ),
            RequestScenario(
                name="Forged calendar selections are denied",
                method="POST",
                user=self.actor,
                view_kwargs=kwargs,
                content_type="application/json",
                data={"inboxes": [str(self.other_inbox.pk)], "users": []},
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Unreadable users cannot be selected for calendars",
                method="POST",
                user=self.owner,
                view_kwargs=kwargs,
                content_type="application/json",
                data={
                    "inboxes": [str(self.source.pk)],
                    "users": [str(self.outsider.pk)],
                },
                expected=ExpectedResult(status_code=403),
            ),
            RequestScenario(
                name="Standard calendar overlays deduplicate events and show readable selected memberships",
                view_name="components_dataview",
                user=self.actor,
                prepare=self.prepare_overlay,
                expected=ExpectedResult(response_validators=self.overlay_rendered),
            ),
            RequestScenario(
                name="A single selected inbox omits other membership dots and events",
                view_name="components_dataview",
                user=self.actor,
                prepare=self.prepare_single_calendar,
                expected=ExpectedResult(
                    response_validators=self.single_calendar_rendered
                ),
            ),
            RequestScenario(
                name="Calendar page requires login",
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=302),
            ),
            RequestScenario(
                name="Unrelated Inbox is hidden",
                user=self.outsider,
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=404),
            ),
            RequestScenario(
                name="Inbox ownership issues a scoped calendar grant",
                user=self.owner,
                view_kwargs=kwargs,
                expected=ExpectedResult(status_code=200),
            ),
            RequestScenario(
                name="Shared selection opens effective calendar and preserves preferences",
                user=self.actor,
                view_kwargs={"inbox_id": self.reference.pk},
                expected=ExpectedResult(response_validators=self.correct_navigation),
            ),
        ]

    def selection_saved(self, response: HttpResponse) -> bool:
        """Resolve readable users to inboxes, persist the selection, and return the ordinary loader."""
        from bloomerp.services.calendar_overlays import calendar_overlay_selection
        from bloomerp.permissions.definition import PermissionToken

        saved = calendar_overlay_selection(self.actor, self.source.pk)
        grant = PermissionToken.verify(
            response.context["token"], audience=str(self.actor.pk)
        )
        restored = self.client.get(
            reverse("inbox_calendar", kwargs={"inbox_id": self.source.pk})
        )
        filters = json.loads(restored.context["calendar_filters"]["filter"])
        self.assertEqual(
            saved, {"inboxes": [str(self.source.pk)], "users": [str(self.owner.pk)]}
        )
        from bloomerp.communication.utils.permissions import accessible_inboxes

        expected = {str(self.source.pk)} | {
            str(pk)
            for pk in accessible_inboxes(self.owner).values_list("pk", flat=True)
        }
        self.assertEqual(
            set(grant.rule.row_permissions[0].conditions[0].value), expected
        )
        self.assertEqual(set(filters[0]["conditions"][0]["value"]), expected)
        self.assertIn('hx-trigger="load"', response.content.decode())
        self.assertNotIn("calendar_overlay_url", response.content.decode())
        return True

    def correct_navigation(self, response: HttpResponse) -> bool:
        """Confirm shared dataview loading, hidden Inbox scope, and unchanged preferences."""
        body = response.content.decode()
        self.reference.refresh_from_db()
        content_type = ContentType.objects.get_for_model(CalendarEvent)
        return (
            reverse(
                "components_dataview",
                kwargs={"content_type_id": content_type.pk},
            )
            in body
            and f"calendar_color_values={self.source.pk}" in body
            and "_arg_hide_filters=inboxes%2Cinboxes__in%2Ccancelled" in body
            and "cancelled=false" in body
            and '<header class="mb-4 flex flex-wrap items-center justify-between gap-3">'
            not in body
            and self.reference.selected
            and UserListViewPreference.objects.count() == self.preference_count
        )

    def prepare_overlay(self, scenario: RequestScenario) -> None:
        """Use the real shared calendar renderer and filter pipeline with two accessible inboxes."""
        self.other_inbox.shared_with_users.add(self.actor)
        private = Inbox.objects.create(
            user=self.outsider, name="Hidden calendar membership"
        )
        self.timed.inboxes.add(private)
        content_type = ContentType.objects.get_for_model(CalendarEvent)
        preference = PreferenceManager(self.actor).get_or_create_selected(
            UserListViewPreference, {"content_type_id": content_type.pk}
        )
        preference.view_type = "calendar"
        preference.options = {
            "calendar": {
                "start_field": "start",
                "end_field": "end",
                "start_date_field": "start_date",
                "end_date_field": "end_date",
                "view_mode": "month",
                "color_grouping_field": "inboxes",
            }
        }
        preference.save()
        scenario.view_kwargs = {"content_type_id": content_type.pk}
        scenario.query_params = {
            "filter": json.dumps(
                [
                    {
                        "connector": "AND",
                        "conditions": [
                            {
                                "field_path": "inboxes",
                                "lookup_id": "values_in",
                                "value": [
                                    str(self.source.pk),
                                    str(self.other_inbox.pk),
                                ],
                            }
                        ],
                    }
                ]
            ),
            "calendar_inbox": str(self.source.pk),
            "calendar_color_field": "inboxes",
            "cancelled": "false",
            "calendar_color_values": f"{self.source.pk},{self.other_inbox.pk}",
            "calendar_color_preferred": str(self.source.pk),
        }

    def prepare_single_calendar(self, scenario: RequestScenario) -> None:
        """Retain two readable calendars but narrow the rendered events and memberships to one."""
        self.prepare_overlay(scenario)
        scenario.query_params["filter"] = json.dumps(
            [
                {
                    "connector": "AND",
                    "conditions": [
                        {
                            "field_path": "inboxes",
                            "lookup_id": "values_in",
                            "value": [str(self.source.pk)],
                        }
                    ],
                }
            ]
        )
        scenario.query_params["calendar_color_values"] = str(self.source.pk)

    def overlay_rendered(self, response: HttpResponse) -> bool:
        """Show the union once, reuse the preferred color, and keep inaccessible names out of the HTML."""
        from bloomerp.dataviews.calendar.grouping import calendar_group_color

        body = response.content.decode()
        return (
            self.calendar_button_count(body, str(self.timed.pk)) == 1
            and self.unplaced.title in body
            and "data-calendar-group-memberships" in body
            and "inbox-calendar-overlay" in body
            and self.source.name in body
            and self.other_inbox.name in body
            and "Hidden calendar membership" not in body
            and calendar_group_color(str(self.source.pk), relation=True) in body
        )

    def single_calendar_rendered(self, response: HttpResponse) -> bool:
        """Do not draw duplicate rows or membership dots for unselected calendars."""
        body = response.content.decode()
        return (
            self.unplaced.title not in body
            and "data-calendar-group-memberships" not in body
            and self.calendar_button_count(body, str(self.timed.pk)) == 1
        )

    def calendar_button_count(self, body: str, object_id: str) -> int:
        """Count event buttons separately from nested field cells that repeat the object's ID."""
        return len(
            re.findall(
                r'<button\b[^>]*\bdata-calendar-event\b[^>]*\bdata-object-id="'
                + re.escape(object_id)
                + r'"',
                body,
            )
        )
